import {T,Kit} from './core.js?v=75';
import {insideRegion} from './village-traffic.js?v=75';
import {COMPLETE_PLAZA} from './complete-plaza-data.js?v=75';

const FLOOR='Einheitlicher Natursteinbelag des vollständigen Dorfplatzes';
const area=ring=>Math.abs(ring.reduce((v,p,i)=>{const q=ring[(i+1)%ring.length];return v+p[0]*q[1]-q[0]*p[1];},0)/2);
function removeShopTurfOverlap(scene){
 const turf=scene.getObjectByName('Durchgängiges Gelände mit ebenen Hausstandflächen und sanften Böschungen');if(!turf)throw new Error('Existing underlying village terrain missing');scene.updateMatrixWorld(true);
 const rings=COMPLETE_PLAZA.patch.flatMap(r=>(r.holes||[]).filter(ring=>{const a=area(ring),x=ring.reduce((v,p)=>v+p[0],0)/ring.length;return a>1&&a<3&&x>-140;}).map(ring=>{const cx=ring.reduce((v,p)=>v+p[0],0)/ring.length,cz=ring.reduce((v,p)=>v+p[1],0)/ring.length;let points=ring.map(([x,z])=>[cx+(x-cx)*1.075,cz+(z-cz)*1.075]);const signed=points.reduce((v,p,i)=>{const q=points[(i+1)%points.length];return v+p[0]*q[1]-q[0]*p[1];},0);if(signed<0)points.reverse();return points;}));
 const g=turf.geometry,attributes=g.attributes,arrays=Object.fromEntries(Object.entries(attributes).map(([key,a])=>[key,Array.from(a.array)])),indices=[],ix=g.index,p=attributes.position;let next=p.count,trimmed=0;
 const vertex=i=>{const w=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(turf.matrixWorld);return {xz:[w.x,w.z],values:Object.fromEntries(Object.entries(attributes).map(([key,a])=>[key,Array.from(a.array.slice(i*a.itemSize,(i+1)*a.itemSize))]))};};
 const lerp=(a,b,t)=>({xz:a.xz.map((x,i)=>x+(b.xz[i]-x)*t),values:Object.fromEntries(Object.keys(attributes).map(key=>[key,a.values[key].map((v,i)=>v+(b.values[key][i]-v)*t)]))});
 const clip=(poly,a,b,inside)=>{const out=[],sign=inside?1:-1,distance=v=>((b[0]-a[0])*(v.xz[1]-a[1])-(b[1]-a[1])*(v.xz[0]-a[0]))*sign;for(let i=0;i<poly.length;i++){const u=poly[i],v=poly[(i+1)%poly.length],du=distance(u),dv=distance(v);if(du>=0)out.push(u);if((du>=0)!==(dv>=0))out.push(lerp(u,v,du/(du-dv)));}return out;};
 const append=poly=>{if(poly.length<3)return;const ids=poly.map(v=>{for(const key of Object.keys(attributes))arrays[key].push(...v.values[key]);return next++;});for(let i=1;i<ids.length-1;i++)indices.push(ids[0],ids[i],ids[i+1]);};
 const bounds=rings.map(r=>({minX:Math.min(...r.map(p=>p[0])),maxX:Math.max(...r.map(p=>p[0])),minZ:Math.min(...r.map(p=>p[1])),maxZ:Math.max(...r.map(p=>p[1]))}));
 for(let i=0;i<ix.count;i+=3){const ids=[ix.getX(i),ix.getX(i+1),ix.getX(i+2)],tri=ids.map(vertex),candidate=bounds.findIndex(b=>Math.max(...tri.map(v=>v.xz[0]))>=b.minX&&Math.min(...tri.map(v=>v.xz[0]))<=b.maxX&&Math.max(...tri.map(v=>v.xz[1]))>=b.minZ&&Math.min(...tri.map(v=>v.xz[1]))<=b.maxZ);if(candidate<0){indices.push(...ids);continue;}let poly=tri;const ring=rings[candidate];for(let j=0;j<ring.length&&poly.length;j++){const a=ring[j],b=ring[(j+1)%ring.length];append(clip(poly,a,b,false));poly=clip(poly,a,b,true);}trimmed++;}
 for(const [key,a]of Object.entries(attributes))g.setAttribute(key,new T.BufferAttribute(new a.array.constructor(arrays[key]),a.itemSize,a.normalized));g.setIndex(indices);g.computeBoundingBox();g.computeBoundingSphere();turf.userData.villageDetailsGroundRepair=true;return {openings:rings.length,trimmedTriangles:trimmed,unchangedOriginalVertices:p.count,marginMeters:.06};
}
function roundedShape(w,h,r){const s=new T.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s;}
function replaceEntrance(scene,m){
 const old=scene.getObjectByName('Dorfeinfahrt Seealm');if(!old)throw new Error('Existing Seealm entrance sign missing');
 const data={...old.userData},position=old.getWorldPosition(new T.Vector3()),rotation=old.getWorldQuaternion(new T.Quaternion()),parent=old.parent,ey=data.groundY,yaw=old.rotation.y;
 const targets=[-.68,.68].map(dx=>new T.Vector3(old.position.x+Math.cos(yaw)*dx,0,old.position.z-Math.sin(yaw)*dx));let removedPosts=0;
 parent.traverse(o=>{if(!o.isInstancedMesh||o.material!==m.frame)return;const kept=[],matrix=new T.Matrix4(),p=new T.Vector3(),q=new T.Quaternion(),s=new T.Vector3();for(let i=0;i<o.count;i++){o.getMatrixAt(i,matrix);matrix.decompose(p,q,s);if(Math.abs(s.x-.045)<1e-6&&Math.abs(s.z-.045)<1e-6&&targets.some(t=>Math.hypot(t.x-p.x,t.z-p.z)<1e-5)){removedPosts++;continue;}kept.push(matrix.clone());}kept.forEach((a,i)=>o.setMatrixAt(i,a));o.count=kept.length;o.instanceMatrix.needsUpdate=true;o.computeBoundingSphere();});
 if(removedPosts!==2)throw new Error('Expected exactly two old entrance posts, found '+removedPosts);old.removeFromParent();
 const g=new T.Group();g.name='Ortsschild Seealm – gelb mit schwarzem Rand und Metallpfosten';g.position.set(position.x,ey,position.z);g.quaternion.copy(rotation);g.userData={...data,villageEntrance:true,text:'Seealm',subtitle:'am Bergsee',groundY:ey,width:1.2,height:.9,referenceStyleVersion:84,singleMetalPole:true};scene.add(g);
 const silver=new T.MeshStandardMaterial({name:'Ortsschild – verzinktes silbergraues Metall',color:'#aeb5b7',metalness:.7,roughness:.42}),k=new Kit(g),centerY=2.03;
 k.cyl(silver,0,1.235,-.053,.035,2.47);const shape=roundedShape(1.2,.9,.045),plate=k.mesh(new T.ExtrudeGeometry(shape,{depth:.022,bevelEnabled:true,bevelThickness:.004,bevelSize:.004,bevelSegments:2,steps:1,curveSegments:12}),silver,'Abgerundete metallene Schildtafel');plate.position.set(0,centerY,-.022);
 const label=m.makeSign('',{width:1200,height:900,background:'#ffcc00',italic:false}),canvas=label.map.image,ctx=canvas.getContext('2d');ctx.clearRect(0,0,1200,900);ctx.fillStyle='#ffcc00';ctx.beginPath();ctx.roundRect(0,0,1200,900,45);ctx.fill();ctx.strokeStyle='#161616';ctx.lineWidth=17;ctx.beginPath();ctx.roundRect(22,22,1156,856,35);ctx.stroke();ctx.fillStyle='#111111';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='500 215px "DejaVu Sans", Arial, sans-serif';ctx.fillText('Seealm',600,350);ctx.font='500 110px "DejaVu Sans", Arial, sans-serif';ctx.fillText('am Bergsee',600,626);label.name='Ortsschild Seealm – schwarze Schrift auf Gelb';label.emissive.set(0);label.emissiveMap=null;label.emissiveIntensity=1;label.roughness=.55;label.map.needsUpdate=true;
 const frontGeometry=new T.ShapeGeometry(shape,12),p=frontGeometry.attributes.position,uv=frontGeometry.attributes.uv;for(let i=0;i<p.count;i++)uv.setXY(i,p.getX(i)/1.2+.5,p.getY(i)/.9+.5);const front=k.mesh(frontGeometry,label,'Seealm · am Bergsee');front.position.set(0,centerY,.005);
 const rim=roundedShape(1.258,.958,.068).getPoints(96).map(p=>new T.Vector3(p.x,p.y+centerY,-.006));rim.push(rim[0].clone());k.mesh(new T.TubeGeometry(new T.CatmullRomCurve3(rim,false,'centripetal'),192,.012,8,false),silver,'Äußerer silberner Schutzrahmen');for(const [x,y]of [[-.42,centerY-.47],[.42,centerY-.47],[-.42,centerY+.47],[.42,centerY+.47]])k.box(silver,x,y,.008,.022,.045,.017);k.finish();return {group:g,removedPosts};
}
export function applyVillageDetails(scene,m,plaza,meadowController){
 const turfRepair=removeShopTurfOverlap(scene);
 const previousCenter=[...plaza.report.center],center=[previousCenter[0],previousCenter[1]+3],y=plaza.report.levelFurnitureHeight,floor=scene.getObjectByName(FLOOR),p=floor.geometry.attributes.position;
 // Retain a continuous surface, the same material and the original UV coordinates.
 for(let i=0;i<p.count;i++){const d=Math.hypot(p.getX(i)-center[0],p.getZ(i)-center[1]);if(d>=5.6)continue;const t=Math.max(0,Math.min(1,(d-4.1)/1.5)),s=t*t*(3-2*t);p.setY(i,y*(1-s)+p.getY(i)*s);}floor.geometry.computeVertexNormals();floor.geometry.computeBoundingBox();floor.geometry.computeBoundingSphere();
 for(const g of [plaza.fountain.group,...plaza.benches])g.position.z+=3;plaza.fountain.group.userData.center=[...center];Object.assign(plaza.report,{version:84,center,previousCenter,shiftMeters:[0,3],centerMethod:'Original paving area centroid, shifted three metres toward the open square and street'});
 // The former circular planting openings have already been closed geometrically.
 // Close their vegetation mask too, including camera-dependent near-field grass.
 let closedMasks=0;scene.userData.completePlazaRepairPatch=scene.userData.completePlazaRepairPatch.map(region=>({...region,holes:(region.holes||[]).filter(ring=>{const a=area(ring);if(a>1&&a<3){closedMasks++;return false;}return true;})}));let removedPlants=0;for(const rows of meadowController.records)for(let i=rows.length-1;i>=0;i--)if(insideRegion(rows[i].x,rows[i].z,scene.userData.completePlazaRepairPatch)){rows.splice(i,1);removedPlants++;}meadowController.prepareExport();
 const entrance=replaceEntrance(scene,m),townhall=scene.getObjectByName('Fassadenschild rathaus');if(!townhall?.userData.townhallSign)throw new Error('Original town hall sign missing');townhall.material=m.makeSign('Rathaus Seealm',{subtitle:'',width:1536,height:300,fontScale:.60,fontFamily:'"DejaVu Sans", Arial, sans-serif',italic:true,foreground:'#eadcc0',background:'#29362d'});townhall.material.name='Dorfbeschriftung rathaus';townhall.material.emissiveIntensity=.13;townhall.userData.text='Rathaus Seealm';
 scene.userData.villageDetails={version:84,fountainCenter:center,previousFountainCenter:previousCenter,shiftMeters:[0,3],benchFrontClearanceMeters:1,turfRepair,closedVegetationMasks:closedMasks,removedPlants,oldEntrancePostsRemoved:entrance.removedPosts,entranceText:'Seealm',entranceSubtitle:'am Bergsee',townhallText:'Rathaus Seealm',unchangedTownhallSignDimensions:[3.5,.54]};scene.updateMatrixWorld(true);return scene.userData.villageDetails;
}
